using System.Collections.Generic;

namespace SWLOR.Game.Server.Service.CraftService;

/// <summary>
/// The values one Fabrication recipe gives the Fabricator minigame. They are set by <c>.FabricatorParameters(...)</c> in the recipe
/// definitions and generated by <see cref="FabricatorParameterProfile"/>.
/// <para>
/// A piece is built as three sub-assemblies: the Frame (the Cutter head), the Shell (the Extruder head) and the Fittings (the
/// Bonder head). Each has a size, the share of the recipe's work it needs, and a quality share, the weight its quality has in the
/// piece's quality. The Fittings take what the Frame and the Shell leave, so a recipe states two numbers of each.
/// </para>
/// </summary>
public sealed class FabricatorParameters : RecipeMinigameParameters
{
    private readonly IReadOnlyList<RecipeParameterValue> _values;

    /// <param name="frameSizePercent">The percentage of the recipe's work that is the Frame.</param>
    /// <param name="shellSizePercent">The percentage of the recipe's work that is the Shell. The Fittings are the rest.</param>
    /// <param name="frameQualityPercent">The percentage of the piece's quality that comes from the Frame.</param>
    /// <param name="shellQualityPercent">The percentage of the piece's quality that comes from the Shell. The Fittings are the rest.</param>
    /// <param name="wearRate">The Machine Condition every Run and Precision Pass costs; hard materials wear the heads faster.</param>
    public FabricatorParameters(
        int frameSizePercent,
        int shellSizePercent,
        int frameQualityPercent,
        int shellQualityPercent,
        int wearRate)
    {
        FrameSizePercent = frameSizePercent;
        ShellSizePercent = shellSizePercent;
        FrameQualityPercent = frameQualityPercent;
        ShellQualityPercent = shellQualityPercent;
        WearRate = wearRate;
        _values = new[]
        {
            new RecipeParameterValue("frameSizePercent", frameSizePercent),
            new RecipeParameterValue("shellSizePercent", shellSizePercent),
            new RecipeParameterValue("frameQualityPercent", frameQualityPercent),
            new RecipeParameterValue("shellQualityPercent", shellQualityPercent),
            new RecipeParameterValue("wearRate", wearRate)
        };
    }

    public int FrameSizePercent { get; }

    public int ShellSizePercent { get; }

    /// <summary>The percentage of the recipe's work that is the Fittings: what the Frame and the Shell leave.</summary>
    public int FittingsSizePercent => 100 - FrameSizePercent - ShellSizePercent;

    public int FrameQualityPercent { get; }

    public int ShellQualityPercent { get; }

    /// <summary>The percentage of the piece's quality that comes from the Fittings: what the Frame and the Shell leave.</summary>
    public int FittingsQualityPercent => 100 - FrameQualityPercent - ShellQualityPercent;

    public int WearRate { get; }

    public override IReadOnlyList<RecipeParameterValue> Values => _values;

    /// <summary>The values a recipe without parameters plays with: an even split and a middling wear.</summary>
    public static FabricatorParameters Fallback { get; } = new(34, 33, 34, 33, 4);
}
